package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;
public final class DwfScreen extends AbstractContainerScreen<DwfMenu>{
 private EditBox search,batch;private boolean continuous,restoredControls;private Button mode;private int sort,materialScroll;
 public DwfScreen(DwfMenu menu,Inventory inv,Component title){super(menu,inv,title);imageWidth=menu.chest==2?340:176;imageHeight=234;inventoryLabelY=140;}
 @Override protected void init(){super.init();search=new EditBox(font,leftPos+8,topPos+25,126,18,Component.literal("Search products or materials"));search.setMaxLength(120);search.setHint(Component.literal(menu.chest==2?"Search / category":"Search storage"));search.setResponder(text->menu.send(1,0,0,0,text));addRenderableWidget(search);addRenderableWidget(Button.builder(Component.literal("Sort"),b->{sort=(sort+1)%3;b.setMessage(Component.literal(new String[]{"Name","Count","Group"}[sort]));menu.send(3,sort,0,0,"");}).bounds(leftPos+137,topPos+25,31,18).build());addRenderableWidget(Button.builder(Component.literal("<"),b->{if(menu.view!=null)menu.send(2,menu.view.page()-1,0,0,"");}).bounds(leftPos+8,topPos+9,18,12).build());addRenderableWidget(Button.builder(Component.literal(">"),b->{if(menu.view!=null&&menu.view.more())menu.send(2,menu.view.page()+1,0,0,"");}).bounds(leftPos+150,topPos+9,18,12).build());
  if(menu.chest==2){batch=new EditBox(font,leftPos+8,topPos+116,35,16,Component.literal("Batch size"));batch.setValue("1");batch.setMaxLength(7);batch.setFilter(t->t.matches("[0-9]*"));addRenderableWidget(batch);addRenderableWidget(Button.builder(Component.literal("Start"),b->menu.send(5,0,continuous?1:0,0,batch.getValue())).bounds(leftPos+46,topPos+116,34,16).build());addRenderableWidget(Button.builder(Component.literal("Pause"),b->menu.send(6,1,0,0,"")).bounds(leftPos+82,topPos+116,40,16).build());addRenderableWidget(Button.builder(Component.literal("Resume"),b->menu.send(6,2,0,0,"")).bounds(leftPos+124,topPos+116,44,16).build());mode=addRenderableWidget(Button.builder(Component.literal(continuous?"Continuous":"Batch"),b->{continuous=!continuous;b.setMessage(Component.literal(continuous?"Continuous":"Batch"));}).bounds(leftPos+8,topPos+134,72,13).build());addRenderableWidget(Button.builder(Component.literal("Stop"),b->menu.send(6,3,0,0,"")).bounds(leftPos+125,topPos+134,43,13).build());}
 }
 @Override public void containerTick(){super.containerTick();if(!restoredControls&&menu.chest==2&&menu.view!=null){restoredControls=true;continuous=menu.view.continuous();mode.setMessage(Component.literal(continuous?"Continuous":"Batch"));batch.setValue(Long.toString(Math.max(1,menu.view.remaining())));}}
 @Override protected void renderBg(GuiGraphics g,float partial,int x,int y){g.fill(leftPos,topPos,leftPos+imageWidth,topPos+imageHeight,0xff17252b);g.fill(leftPos+4,topPos+46,leftPos+172,topPos+108,0xff0b141a);if(menu.chest==2)g.fill(leftPos+178,topPos+23,leftPos+336,topPos+229,0xff0d1a20);for(var slot:menu.slots)g.fill(leftPos+slot.x-1,topPos+slot.y-1,leftPos+slot.x+17,topPos+slot.y+17,0xff53636b);for(var slot:menu.slots)g.fill(leftPos+slot.x,topPos+slot.y,leftPos+slot.x+16,topPos+slot.y+16,0xff23343d);}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){g.drawCenteredString(font,title,88,0,0xffffff);var v=menu.view;if(v==null)return;g.drawCenteredString(font,"Page "+(v.page()+1),88,12,0x9cb8c4);if(menu.chest<2){g.drawString(font,compact(v.total())+" / "+compact(v.capacity())+" items",8,114,0xd6e4e9,false);g.drawString(font,v.variants()+" / "+v.variantLimit()+" variants",8,125,0xa8c3cf,false);}else{g.fill(8,109,168,112,0xff384951);g.fill(8,109,8+(int)(160*Math.min(1,(double)v.progress()/Math.max(1,v.duration()))),112,0xffd9ab48);}
  if(menu.chest<2&&!v.details().isEmpty()&&v.details().get(0).startsWith("RS 1 view LIMITED"))g.drawString(font,"RS view limited",8,136,0xffdca63a,false);
  if(menu.chest==2){int lineY=28;for(var line:font.split(Component.literal(v.productName()),146)){g.drawString(font,line,184,lineY,0xffffff,false);lineY+=10;}g.drawString(font,v.status().replace('_',' '),184,Math.max(58,lineY+3),0xd9b36a,false);g.drawString(font,"Time: "+(v.duration()/20f)+" s",184,80,0x9cb8c4,false);g.drawString(font,v.continuous()?"Continuous":"Remaining: "+v.remaining(),184,92,0x9cb8c4,false);g.drawString(font,"Materials",184,106,0xffffff,false);g.drawString(font,"Have / Need (1 cycle)",184,117,0x9cb8c4,false);materialScroll=Math.max(0,Math.min(materialScroll,Math.max(0,v.materials().size()-4)));for(int i=0;i<4&&materialScroll+i<v.materials().size();i++){var material=v.materials().get(materialScroll+i);int at=130+i*24;g.renderItem(material.icon(),184,at);g.drawString(font,font.plainSubstrByWidth(material.name(),123),204,at,0xdce8ef,false);String have=v.creative()?"Unlimited":material.available()<0?"Check":compact(material.available());String count=have+" / "+compact(material.required());g.drawString(font,count,204,at+11,v.creative()||material.available()>=material.required()?0x91d29b:0xe5ad7d,false);}if(v.materials().size()>4){int track=94,thumb=Math.max(12,track*4/v.materials().size()),at=130+(track-thumb)*materialScroll/Math.max(1,v.materials().size()-4);g.fill(331,130,333,224,0xff243c48);g.fill(331,at,333,at+thumb,0xff88a8b8);}}

  for(int i=0;i<Math.min(27,v.counts().size());i++){var slot=menu.slots.get(i);String n=compact(v.counts().get(i));g.pose().pushPose();g.pose().translate(slot.x+16,slot.y+11,210);float scale=Math.min(.7f,16f/Math.max(1,font.width(n)));g.pose().scale(scale,scale,1);g.drawString(font,n,-font.width(n),0,0xffffff,true);g.pose().popPose();}
 }
 @Override public void render(GuiGraphics g,int x,int y,float partial){renderBackground(g);super.render(g,x,y,partial);renderTooltip(g,x,y);var v=menu.view;if(menu.chest==2&&v!=null&&x>=leftPos+182&&x<leftPos+330&&y>=topPos+130&&y<topPos+226){int index=materialScroll+(y-topPos-130)/24;if(index<v.materials().size()){var material=v.materials().get(index);var lines=new java.util.ArrayList<Component>();lines.add(Component.literal(material.name()));lines.add(Component.literal("Available: "+(v.creative()?"Unlimited (creative)":material.available()<0?"Checked when production starts":String.format(java.util.Locale.ROOT,"%,d",material.available()))));lines.add(Component.literal(String.format(java.util.Locale.ROOT,"Required per production cycle: %,d",material.required())));g.renderTooltip(font,lines.stream().map(Component::getVisualOrderText).toList(),x,y);}}if(v!=null&&y>=topPos+109&&y<topPos+149&&x>=leftPos&&x<leftPos+176){var lines=new java.util.ArrayList<net.minecraft.util.FormattedCharSequence>();if(menu.chest<2){lines.add(Component.literal(String.format(java.util.Locale.ROOT,"Stored: %,d / %,d",v.total(),v.capacity())).getVisualOrderText());}else lines.addAll(font.split(Component.literal(v.status()),170));if(menu.chest<2)for(String d:v.details())lines.addAll(font.split(Component.literal(d),170));g.renderTooltip(font,lines,x,y);}}
 @Override protected void slotClicked(net.minecraft.world.inventory.Slot slot,int index,int button,net.minecraft.world.inventory.ClickType type){if(menu.chest==2&&index>=0&&index<27){materialScroll=0;menu.send(4,index,0,0,"");return;}super.slotClicked(slot,index,button,type);}
 @Override protected java.util.List<Component>getTooltipFromContainerItem(net.minecraft.world.item.ItemStack item){var lines=new java.util.ArrayList<>(super.getTooltipFromContainerItem(item));if(menu.chest<2&&menu.view!=null&&hoveredSlot!=null&&hoveredSlot.index<27&&hoveredSlot.index<menu.view.counts().size())lines.add(Component.literal(String.format(java.util.Locale.ROOT,"Stored: %,d",menu.view.counts().get(hoveredSlot.index))));return lines;}
 @Override public boolean mouseScrolled(double x,double y,double delta){if(menu.chest==2&&x>=leftPos+178&&x<leftPos+340&&y>=topPos+124&&y<topPos+228&&menu.view!=null){materialScroll=Math.max(0,Math.min(Math.max(0,menu.view.materials().size()-4),materialScroll+(delta<0?1:-1)));return true;}return super.mouseScrolled(x,y,delta);}
 private static String compact(long n){return n>=1_000_000_000?String.format(java.util.Locale.ROOT,"%.1fb",n/1e9).replace(".0",""):n>=1_000_000?String.format(java.util.Locale.ROOT,"%.1fm",n/1e6).replace(".0",""):n>=10_000?String.format(java.util.Locale.ROOT,"%.1fk",n/1e3).replace(".0",""):Long.toString(n);}
}
